3	import com.fasterxml.jackson.databind.ObjectMapper;
4	import jakarta.validation.Valid;
5	import jakarta.validation.constraints.Min;
6	import org.springframework.http.ResponseEntity;
7	import org.springframework.validation.annotation.Validated;
8	import org.springframework.web.bind.annotation.GetMapping;
9	import org.springframework.web.bind.annotation.PathVariable;
10	import org.springframework.web.bind.annotation.PostMapping;
11	import org.springframework.web.bind.annotation.RequestBody;
12	import org.springframework.web.bind.annotation.RequestMapping;
13	import org.springframework.web.bind.annotation.RestController;
14	
15	import java.util.List;
16	
17	/**
18	 * 现场观测离线合并 API：创建、离线提交（三方合并）、冲突显式解决、删除、当前/历史版本与解决记录查询。
19	 */
20	@RestController
21	@RequestMapping("/api/observations")
22	@Validated
23	public class ObservationController {
24	
25	    private final ObservationService observationService;
26	    private final ObjectMapper objectMapper;
27	
28	    public ObservationController(ObservationService observationService, ObjectMapper objectMapper) {
29	        this.observationService = observationService;
30	        this.objectMapper = objectMapper;
31	    }
32	
33	    /**
34	     * 创建观测记录，初始版本为 1。
35	     */
36	    @PostMapping
37	    public ResponseEntity<ObservationResponse> create(@Valid @RequestBody CreateObservationRequest request) {
38	        ObservationService.WriteOutcome outcome = observationService.create(request);
39	        return ResponseEntity.status(outcome.status()).body(outcome.body());
40	    }
41	
42	    /**
43	     * 离线提交：携带 baseVersion 与三个字段完整候选值，执行三方合并。
44	     */
45	    @PostMapping("/{observationId}/merge")
46	    public ResponseEntity<ObservationResponse> merge(@PathVariable String observationId,
47	                                                     @Valid @RequestBody MergeObservationRequest request) {
48	        ObservationService.WriteOutcome outcome = observationService.merge(observationId, request);
49	        return ResponseEntity.status(outcome.status()).body(outcome.body());
50	    }
51	
52	    /**
53	     * 删除观测记录：expectedVersion 匹配当前版本时生成新版本墓碑。
54	     */
55	    @PostMapping("/{observationId}/delete")
56	    public ResponseEntity<ObservationResponse> delete(@PathVariable String observationId,
57	                                                      @Valid @RequestBody DeleteObservationRequest request) {
58	        ObservationService.WriteOutcome outcome = observationService.delete(observationId, request);
59	        return ResponseEntity.status(outcome.status()).body(outcome.body());
60	    }
61	
62	    /**
63	     * 查询当前内容；墓碑只返回删除状态和版本。
64	     */
65	    @GetMapping("/{observationId}")
66	    public ObservationResponse getCurrent(@PathVariable String observationId) {
67	        return observationService.getCurrent(observationId);
68	    }
69	
70	    /**
71	     * 查询指定历史版本；墓碑版本只返回删除状态和版本。
72	     */
73	    @GetMapping("/{observationId}/versions/{version}")
74	    public ObservationResponse getVersion(@PathVariable String observationId,
75	                                          @PathVariable @Min(1) int version) {
76	        return observationService.getVersion(observationId, version);
77	    }
78	
79	    /**
80	     * 显式冲突解决：提交候选值与冲突字段选择，原子生成新版本（或无变化）与不可变解决记录。
81	     */
82	    @PostMapping("/{observationId}/resolve")
83	    public ResponseEntity<ResolutionResponse> resolve(@PathVariable String observationId,
84	                                                      @Valid @RequestBody ResolveConflictRequest request) {
85	        ObservationService.ResolveOutcome outcome = observationService.resolveConflict(observationId, request);
86	        return ResponseEntity.status(outcome.status()).body(outcome.body());
87	    }
88	
89	    /**
90	     * 按全局唯一 resolutionId 查询解决记录。
91	     */
92	    @GetMapping("/resolutions/{resolutionId}")
93	    public ResolutionResponse getResolution(@PathVariable String resolutionId) {
94	        ResolutionRecord record = observationService.getResolution(resolutionId);
95	        return resolutionResponse(record);
96	    }
97	
98	    /**
99	     * 按 observationId 查询解决历史，按版本先后排序。
