    }

    @Test
    void nonCurrentVersionReturns409() throws Exception {
        createSyntheticObservations();
        // 合并使 obs-t1 前进到版本 2，导线仍引用版本 1
        Map<String, Object> mergeBody = new LinkedHashMap<>();
        mergeBody.put("requestId", "req-m1");
